{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

var (
	backend             string
	backendS3Bucket    string
	kmsKeyAlias        string
	retries             int
	retryMode           string
	verbose             bool
)

func main() {
	rootCmd := &cobra.Command{
		Use:   "chamber",
		Short: "CLI for storing secrets",
		SilenceUsage: true,
	}

	rootCmd.PersistentFlags().StringVarP(&backend, "backend", "b", "ssm", "Backend to use; AKA $CHAMBER_SECRET_BACKEND\n\tnull: no-op\n\tssm: SSM Parameter Store\n\tsecretsmanager: Secrets Manager\n\ts3: S3; requires --backend-s3-bucket\n\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	rootCmd.PersistentFlags().StringVar(&backendS3Bucket, "backend-s3-bucket", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	rootCmd.PersistentFlags().StringVar(&kmsKeyAlias, "kms-key-alias", "alias/parameter_store_key", "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	rootCmd.PersistentFlags().IntVarP(&retries, "retries", "r", 10, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	rootCmd.PersistentFlags().StringVar(&retryMode, "retry-mode", "standard", "For SSM, the model used to retry requests\n  standard\n  adaptive")
	rootCmd.PersistentFlags().BoolVar(&verbose, "verbose", false, "Print more information to STDERR")

	rootCmd.AddCommand(newWriteCommand())
	rootCmd.AddCommand(newListCommand())
	rootCmd.AddCommand(newListServicesCommand())
	rootCmd.AddCommand(newReadCommand())
	rootCmd.AddCommand(newDeleteCommand())
	rootCmd.AddCommand(newHistoryCommand())
	rootCmd.AddCommand(newEnvCommand())
	rootCmd.AddCommand(newExecCommand())
	rootCmd.AddCommand(newExportCommand())
	rootCmd.AddCommand(newImportCommand())
	rootCmd.AddCommand(newFindCommand())
	rootCmd.AddCommand(newTagCommand())
	rootCmd.AddCommand(newVersionCommand())

	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func newWriteCommand() *cobra.Command {
	var tags string
	cmd := &cobra.Command{
		Use:   "write <service> <key> <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if backend == "null" {
				return fmt.Errorf("Write is not implemented for Null Store")
			}
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().StringVar(&tags, "tags", "", "Tagging on write")
	return cmd
}

func newListCommand() *cobra.Command {
	var expand bool
	var time bool
	var user bool
	var version bool
	cmd := &cobra.Command{
		Use:   "list <service>",
		Short: "List the secrets set for a service",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVarP(&expand, "expand", "e", false, "Expand parameter list with values")
	cmd.Flags().BoolVarP(&time, "time", "t", false, "Sort by modified time")
	cmd.Flags().BoolVarP(&user, "user", "u", false, "Sort by user")
	cmd.Flags().BoolVarP(&version, "version", "v", false, "Sort by version")
	return cmd
}

func newListServicesCommand() *cobra.Command {
	var secrets bool
	cmd := &cobra.Command{
		Use:   "list-services <service>",
		Short: "List services",
		RunE: func(cmd *cobra.Command, args []string) error {
			if backend == "null" {
				fmt.Println("Service")
				return nil
			}
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVarP(&secrets, "secrets", "s", false, "Include secret names in the list")
	return cmd
}

func newReadCommand() *cobra.Command {
	var quiet bool
	var version int
	cmd := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read a specific secret from the parameter store",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if backend == "null" {
				return fmt.Errorf("Failed to read: Not implemented for Null Store")
			}
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVarP(&quiet, "quiet", "q", false, "Only print the secret")
	cmd.Flags().IntVarP(&version, "version", "v", -1, "The version number of the secret. Defaults to latest.")
	return cmd
}

func newDeleteCommand() *cobra.Command {
	var exactKey bool
	cmd := &cobra.Command{
		Use:   "delete <service> <key>",
		Short: "Delete a secret, including all versions",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVar(&exactKey, "exact-key", false, "Prevent normalization of the provided key in order to delete any keys that match the exact provided casing.")
	return cmd
}

func newHistoryCommand() *cobra.Command {
	return &cobra.Command{
		Use:   "history <service> <key>",
		Short: "View the history of a secret",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
}

func newEnvCommand() *cobra.Command {
	var preserveCase bool
	var escapeStrings bool
	cmd := &cobra.Command{
		Use:   "env <service>",
		Short: "Print the secrets from the parameter store in a format to export as environment variables",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVarP(&preserveCase, "preserve-case", "p", false, "preserve variable name case")
	cmd.Flags().BoolVarP(&escapeStrings, "escape-strings", "e", false, "escape special characters in values")
	return cmd
}

func newExecCommand() *cobra.Command {
	var pristine bool
	var strict bool
	var strictValue string
	cmd := &cobra.Command{
		Use:   "exec <service...> -- <command> [<arg...>]",
		Short: "Executes a command with secrets loaded into the environment",
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVar(&pristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	cmd.Flags().BoolVar(&strict, "strict", false, "enable strict mode")
	cmd.Flags().StringVar(&strictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	return cmd
}

func newExportCommand() *cobra.Command {
	var format string
	var outputFile string
	cmd := &cobra.Command{
		Use:   "export <service...>",
		Short: "Exports parameters in the specified format",
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().StringVarP(&format, "format", "f", "json", "Output format (json, yaml, java-properties, csv, tsv, dotenv, tfvars)")
	cmd.Flags().StringVarP(&outputFile, "output-file", "o", "", "Output file (default is standard output)")
	return cmd
}

func newImportCommand() *cobra.Command {
	var normalizeKeys bool
	cmd := &cobra.Command{
		Use:   "import <service> <file|->",
		Short: "import secrets from json or yaml",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVar(&normalizeKeys, "normalize-keys", false, "Normalize keys to match how chamber write would handle them. If not specified, keys will be written exactly how they are defined in the import source.")
	return cmd
}

func newFindCommand() *cobra.Command {
	var byValue bool
	cmd := &cobra.Command{
		Use:   "find <secret name>",
		Short: "Find the given secret across all services",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return fmt.Errorf("not implemented")
		},
	}
	cmd.Flags().BoolVarP(&byValue, "by-value", "v", false, "Find parameters by value")
	return cmd
}

func newTagCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "tag",
		Short: "work with tags on secrets",
	}
	cmd.AddCommand(&cobra.Command{
		Use:   "delete <service> <key>",
		Short: "Delete tags for a specific secret",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error { return nil },
	})
	cmd.AddCommand(&cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read tags for a specific secret",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error { return nil },
	})
	cmd.AddCommand(&cobra.Command{
		Use:   "write <service> <key> <tag1=val1> [tag2=val2]...",
		Short: "Write tags for a specific secret",
		Args:  cobra.MinimumNArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error { return nil },
	})
	return cmd
}

func newVersionCommand() *cobra.Command {
	return &cobra.Command{
		Use:   "version",
		Short: "print version",
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Println("chamber dev")
		},
	}
}
EOF
