				kmsKeyAlias = args[i+1]
				i++
			} else if arg == "-r" || arg == "--retries" {
				fmt.Sscanf(args[i+1], "%d", &retries)
				i++
			} else if arg == "--retry-mode" {
				retryMode = args[i+1]
				i++
			} else if arg == "--verbose" {
				verbose = true
			}
		} else if command == "" {
			command = arg
		} else {
			cmdArgs = append(cmdArgs, arg)
		}
	}

	switch command {
