		handleListServices(cmdArgs)
	case "read":
		handleRead(cmdArgs)
	case "delete":
		handleDelete(cmdArgs)
	case "history":
		handleHistory(cmdArgs)
	case "env":
		handleEnv(cmdArgs)
	case "exec":
		handleExec(cmdArgs)
	case "export":
		handleExport(cmdArgs)
	case "import":
		handleImport(cmdArgs)
	case "find":
		handleFind(cmdArgs)
	case "tag":
		handleTag(cmdArgs)
	default:
		fmt.Printf("Unknown command %q\n", command)
		os.Exit(1)
	}
}

