		fmt.Fprintln(os.Stderr, "Error: Write is not implemented for Null Store")
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "Error: operation error %s: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded\n", strings.ToUpper(backend))
	os.Exit(1)
}

