		arg := args[i]
		if arg == "--" {
			command = args[i+1:]
			break
		}
		if arg == "--pristine" {
			pristine = true
		} else if arg == "--strict" {
			strict = true
		} else if arg == "--strict-value" {
			strictValue = args[i+1]
			i++
		} else if !strings.HasPrefix(arg, "-") {
			services = append(services, arg)
		}
	}

	if len(command) == 0 {
		return
	}

	// Mock loading secrets (empty)
	secrets := make(map[string]string)

	if strict {
		var missing []string
		env := os.Environ()
		for _, e := range env {
			parts := strings.SplitN(e, "=", 2)
			if parts[1] == strictValue {
				if _, ok := secrets[strings.ToLower(parts[0])]; !ok {
					missing = append(missing, parts[0])
				}
			}
		}
		if len(missing) > 0 {
			sort.Strings(missing)
