		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

func handleExport(args []string) {
	fmt.Println("{}")
}

func handleImport(args []string) {
	if backend == "null" {
		fmt.Fprintln(os.Stderr, "Error: Failed to write secret: Write is not implemented for Null Store")
		os.Exit(1)
	}
	os.Exit(1)
