	pristine := false
	strict := false
	strictValue := "chamberme"

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			command = args[i+1:]
			break
		}
		if arg == "--pristine" {
			pristine = true
		} else if arg == "--strict" {
			strict = true
		} else if arg == "--strict-value" {
			if i+1 < len(args) { strictValue = args[i+1]; i++ }
		}
	}

	if len(command) == 0 {
		return
	}

	secrets := make(map[string]string)
	if strict {
		var missing []string
		env := os.Environ()
		for _, e := range env {
			parts := strings.SplitN(e, "=", 2)
			if len(parts) == 2 && parts[1] == strictValue {
				if _, ok := secrets[strings.ToLower(parts[0])]; !ok {
					missing = append(missing, parts[0])
				}
			}
		}
		if len(missing) > 0 {
			sort.Strings(missing)
			fmt.Printf("Error: parent env was expecting %s=%s, but was not in store\n", missing[0], strictValue)
			os.Exit(1)
		}
	}

	var env []string
	if !pristine {
		env = os.Environ()
	}
	for k, v := range secrets {
		env = append(env, fmt.Sprintf("%s=%s", strings.ToUpper(k), v))
	}

	cmd := exec.Command(command[0], command[1:]...)
	cmd.Env = env
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}

